graph.register({
  id: provider,
  kind: 'service',
  dependencies: [],
  start: () => ({ value: { ready: true }, release: () => undefined })
})
const consumer = 'consumer' as IGraphNodeId
graph.register({
  id: consumer,
  kind: 'consumer',
  dependencies: [{ provider, required: true }],
  start: ({ get }) => ({ value: get(provider), release: () => undefined })
})
await graph.ready()
const service = graph.get<{ readonly ready: boolean }>(consumer, provider)
await graph.dispose()

type IGraphNodeDefinition<T> = {
  readonly id: IGraphNodeId
  readonly kind: string
  readonly dependencies: readonly { readonly provider: IGraphNodeId; readonly required: true }[]
  readonly start: (
    context: IGraphStartContext
  ) => IGraphNodeInstance<T> | PromiseLike<IGraphNodeInstance<T>>
}

type IGraphNodeDefinition<T> = {
